-- 中文作文工作室：補足 5CW1–5CW4 至80題，建立作文輸入、儲存、自動評改及老師評語資料表。
begin;

create table if not exists public.writing_prompts(
  id bigint generated by default as identity primary key,
  node_id bigint not null references public.curriculum_nodes(id) on delete cascade,
  genre text not null, title text not null, instruction text not null,
  min_chars integer not null default 350, max_chars integer not null default 650,
  guidance jsonb not null default '[]'::jsonb, status text not null default 'published',
  sort_order integer not null default 0, created_at timestamptz not null default now(),
  unique(node_id,title)
);
create table if not exists public.writing_submissions(
  id bigint generated by default as identity primary key,
  student_id uuid not null references auth.users(id) on delete cascade,
  prompt_id bigint not null references public.writing_prompts(id) on delete cascade,
  content text not null, char_count integer not null,
  automated_score integer not null, rubric_breakdown jsonb not null default '{}'::jsonb,
  automated_feedback text not null, teacher_score integer,
  teacher_feedback text, status text not null default 'submitted',
  submitted_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists writing_submissions_student_idx on public.writing_submissions(student_id,submitted_at desc);
alter table public.writing_prompts enable row level security;
alter table public.writing_submissions enable row level security;
drop policy if exists writing_prompts_read on public.writing_prompts;
create policy writing_prompts_read on public.writing_prompts for select to authenticated using(status='published');
drop policy if exists writing_submissions_own_read on public.writing_submissions;
create policy writing_submissions_own_read on public.writing_submissions for select to authenticated using(student_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists writing_submissions_own_insert on public.writing_submissions;
create policy writing_submissions_own_insert on public.writing_submissions for insert to authenticated with check(student_id=auth.uid());
drop policy if exists writing_submissions_admin_update on public.writing_submissions;
create policy writing_submissions_admin_update on public.writing_submissions for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));

create temporary table tmp_prompts(node_code text,genre text,title text,instruction text,min_chars int,max_chars int,guidance jsonb,sort_order int) on commit drop;
select n.id,t.genre,t.title,t.instruction,t.min_chars,t.max_chars,t.guidance,t.sort_order,'published'
from tmp_prompts t join public.curriculum_nodes n on n.code=t.node_code
on conflict(node_id,title) do update set instruction=excluded.instruction,min_chars=excluded.min_chars,max_chars=excluded.max_chars,guidance=excluded.guidance,sort_order=excluded.sort_order,status='published';

create temporary table tmp_extra_questions(node_code text,question_text text,options jsonb,correct_answer jsonb,explanation text,difficulty int) on commit drop;
select n.id,'multiple_choice',t.question_text,t.options,t.difficulty,'teacher','published'
from tmp_extra_questions t join public.curriculum_nodes n on n.code=t.node_code
where not exists(select 1 from public.questions q where q.node_id=n.id and q.question_text=t.question_text);
select q.id,t.correct_answer,t.explanation,'完成初稿後，檢查切題、結構、字詞和標點。'
from tmp_extra_questions t join public.curriculum_nodes n on n.code=t.node_code join public.questions q on q.node_id=n.id and q.question_text=t.question_text
on conflict(question_id) do update set correct_answer=excluded.correct_answer,explanation=excluded.explanation,hint=excluded.hint;

create or replace function public.start_writing_task(p_node_id bigint)
returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.writing_prompts;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  select * into p from public.writing_prompts where node_id=p_node_id and status='published' order by random() limit 1;
  if p.id is null then return jsonb_build_object('success',false,'reason','no_prompt'); end if;
  return jsonb_build_object('success',true,'prompt_id',p.id,'genre',p.genre,'title',p.title,'instruction',p.instruction,'min_chars',p.min_chars,'max_chars',p.max_chars,'guidance',p.guidance);
end $$;

create or replace function public.submit_writing_task(p_prompt_id bigint,p_content text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.writing_prompts; chars int; paras int; punct int; length_score int; paragraph_score int; punctuation_score int; content_score int; total int; keyword_hits int; result_id bigint; feedback text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  select * into p from public.writing_prompts where id=p_prompt_id and status='published';
  if p.id is null then return jsonb_build_object('success',false,'reason','prompt_not_found'); end if;
  chars:=char_length(regexp_replace(coalesce(p_content,''),'[[:space:]]','','g'));
  if chars<50 then return jsonb_build_object('success',false,'reason','too_short'); end if;
  paras:=greatest(1,array_length(regexp_split_to_array(trim(p_content),E'\n[[:space:]]*\n'),1));
  punct:=char_length(p_content)-char_length(regexp_replace(p_content,'[，。！？；：、]','','g'));
  length_score:=case when chars between p.min_chars and p.max_chars then 30 when chars>=p.min_chars*0.75 then 22 when chars>=p.min_chars*0.5 then 15 else 8 end;
  paragraph_score:=case when paras>=4 then 20 when paras=3 then 17 when paras=2 then 11 else 5 end;
  punctuation_score:=case when punct>=14 then 20 when punct>=9 then 15 when punct>=5 then 10 else 5 end;
  select count(*) into keyword_hits from jsonb_array_elements_text(p.guidance) k where position(k in p_content)>0;
  content_score:=least(30,10+keyword_hits*5);
  total:=length_score+paragraph_score+punctuation_score+content_score;
  feedback:=case when length_score<22 then '篇幅稍短，可補充具體經過或例子。 ' else '篇幅完整。 ' end || case when paragraph_score<17 then '建議按內容分成至少三段。 ' else '段落安排清楚。 ' end || case when punctuation_score<15 then '請檢查句號、逗號和其他標點。 ' else '標點運用大致充足。 ' end || case when content_score<25 then '可加入更多題目要求的重點。' else '內容能回應主要寫作要求。' end;
  values(auth.uid(),p.id,p_content,chars,total,jsonb_build_object('篇幅',length_score,'段落',paragraph_score,'標點',punctuation_score,'內容重點',content_score),feedback) returning id into result_id;
  return jsonb_build_object('success',true,'submission_id',result_id,'score',total,'char_count',chars,'rubric',jsonb_build_object('篇幅',length_score,'段落',paragraph_score,'標點',punctuation_score,'內容重點',content_score),'feedback',feedback);
end $$;
grant execute on function public.start_writing_task(bigint) to authenticated;
grant execute on function public.submit_writing_task(bigint,text) to authenticated;
commit;

select n.code,n.title_zh,count(q.id) filter(where q.status='published') as skill_questions,count(distinct wp.id) as writing_prompts
from public.curriculum_nodes n left join public.questions q on q.node_id=n.id left join public.writing_prompts wp on wp.node_id=n.id
where n.code in('5CW1','5CW2','5CW3','5CW4') group by n.code,n.title_zh order by n.code;
